import { test, describe, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Fake pricing gateway (in-process double of the downstream pricing API).
const prices = { A: 10, B: 25, C: 33.34, D: 0.1, E: 100, F: 100.5 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const totalOf = async (items) => (await (await post({ items })).json()).total

describe('POST /orders', () => {
  test('201 with id, items echoed and total', async () => {
    const items = [{ sku: 'A', qty: 2 }]
    const res = await post({ items })
    assert.equal(res.status, 201)
    assert.match(res.headers.get('content-type'), /application\/json/)
    const body = await res.json()
    assert.equal(typeof body.id, 'string')
    assert.deepEqual(body.items, items)
    assert.equal(body.total, 20)
  })

  test('sums unit price * qty across items without discount at or below 100', async () => {
    assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 4 }]), 120 * 0 + 120 - 0 === 120 ? 108 : -1)
  })

  test('exactly 100 gets no discount (threshold is strictly > 100)', async () => {
    assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
  })

  test('just over 100 gets 10% off', async () => {
    assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90) // 100.5 -> 90.45 -> 90
  })

  // CHARACTERIZATION: current behaviour may be unintended — the same flat 10% applies to every
  // order above 100; there is no larger-order tier, so 1000 and 101 are discounted identically.
  test('discount is a flat 10% regardless of order size', async () => {
    assert.equal(await totalOf([{ sku: 'A', qty: 101 }]), 909) // 1010 -> 909
    assert.equal(await totalOf([{ sku: 'A', qty: 1000 }]), 9000)
    assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  })

  // CHARACTERIZATION: current behaviour may be unintended — total is Math.floor'd to whole euros
  // after discount, so cents are silently dropped (always in the customer's favour or the shop's loss).
  test('total is floored to whole euros, dropping cents', async () => {
    assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 33) // 33.34
    assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 90) // 100.02 -> 90.018
    assert.equal(await totalOf([{ sku: 'D', qty: 9 }]), 0) // 0.9
  })

  // CHARACTERIZATION: current behaviour may be unintended — the discount is judged on the
  // pre-discount total with floating point math (0.1 * 3 is 0.30000000000000004), then floored.
  test('floating point sums are floored after the fact', async () => {
    assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 0)
  })

  test('ids are distinct per order', async () => {
    const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
    const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
    assert.notEqual(a.id, b.id)
  })

  for (const [name, body, raw] of [
    ['missing items', {}],
    ['empty items', { items: [] }],
    ['items not an array', { items: 'A' }],
    ['invalid JSON', undefined, '{nope'],
    ['empty body', undefined, ''],
  ]) {
    test(`400 items required: ${name}`, async () => {
      const res = await post(body, raw)
      assert.equal(res.status, 400)
      assert.deepEqual(await res.json(), { error: 'items required' })
    })
  }
})

describe('GET /orders/:id', () => {
  test('200 returns the stored order', async () => {
    const created = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
    const res = await fetch(`${base}/orders/${created.id}`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), created)
  })

  // CHARACTERIZATION: current behaviour may be unintended — an unknown id answers 200, not 404.
  test('unknown id answers 200 {error: not found}', async () => {
    const res = await fetch(`${base}/orders/does-not-exist`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), { error: 'not found' })
  })
})

describe('unrouted requests', () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['GET', '/orders/1/x']]) {
    test(`404 no route: ${method} ${path}`, async () => {
      const res = await fetch(`${base}${path}`, { method })
      assert.equal(res.status, 404)
      assert.deepEqual(await res.json(), { error: 'no route' })
    })
  }
})
EOF
